      if (p === 0) { hbox(x, sc, NEON.cyan); htext(x, sc, 'BEAST', 182, BOX.y + BOX.h / 2 + 2, 52, { fill: NEON.lime, glow: NEON.lime }); htext(x, sc, 'PINBALL', 362, BOX.y + BOX.h / 2 + 4, 40, { glow: NEON.cyan });
        hpill(x, sc, PL, NEON.cyan); htext(x, sc, 'FREE PLAY', PL.x + PL.w / 2 + 2, ROW.y + 19, 18, { glow: NEON.cyan, maxW: PL.w - 34 });
        hpill(x, sc, PR, NEON.lime); htext(x, sc, 'BY OGBE', PR.x + PR.w / 2 + 2, ROW.y + 19, 20, { fill: NEON.lime, glow: NEON.lime, maxW: PR.w - 34 }); }
      else if (p === 1) { hbox(x, sc, NEON.mag); htext(x, sc, 'PRESS START', 265, BOX.y + BOX.h / 2 + 2, 48, { fill: h.blink ? '#fff' : NEON.lime, glow: NEON.lime, maxW: 430 }); wide('SPACE / TAP PLAY', NEON.cyan); }
