      const x = R.hudC.getContext('2d'); x.setTransform(1, 0, 0, 1, 0, 0); x.clearRect(0, 0, R.hudC.width, R.hudC.height); x.scale(R.hudC.width / LW, R.hudC.height / DMD_H);
