    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = Math.min(1, 0.45 + 0.25 * Math.sin(t * 3 + b.idx * 2) + f * 0.6); blit(ctx, ring(col, r + 12, r + 12, 2.4), b.x, b.y);
    if (f > 0) { ctx.globalAlpha = f; blit(ctx, glow(col, 48), b.x, b.y, (r * 3) / 48); ctx.globalAlpha = f * 0.9; blit(ctx, glow('#ffffff', 24, 0.9), b.x, b.y, cr / 22); }
