    fx.cyan = Math.max(0, fx.cyan - d); fx.lime = Math.max(0, fx.lime - d); fx.mag = Math.max(0, fx.mag - d);
    let bf = 0; for (const b of def.bumpers) bf = Math.max(bf, b.flash || 0); if (bf > (P.bf || 0) + 0.2) fx.lime = Math.max(fx.lime, 0.75); P.bf = bf;
